entries[118262] = { ["name"] = "Leuchtende Traumblüte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versetzt den Trinkenden in einen Zustand höchster Konzentration, in dem er im Verlauf von 10 Sek. bis zu ( 255 * 10) Mana regeneriert, aber wehrlos ist, bis die Konzentration gebrochen wird. (5 Min Abklingzeit)" }
entries[118264] = { ["name"] = "Gezackter Leerenkristall", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Schwert\n9 - 15 Schaden Geschwindigkeit 3.60\n(3.3 Schaden pro Sekunde)\n+5 Stärke\n+7 Ausdauer\nErhöht Eure Tempowertung um + 5.\nErhöht Eure Meisterschaftswertung um + 5.\nHaltbarkeit 100 / 100\nAnlegen: Eure Angriffe haben eine Chance, Eurem Gegner durch Leerenenergie 58 Schaden zuzufügen. (Procchance: 15%, 1.417Min. Abklingzeit)\nVerkaufspreis:" }
entries[118265] = { ["name"] = "Hallender Verrat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stille umfängt Euch und lässt Euch das schlagende Herz Eures Gegners erkennen. (2 Min Abklingzeit)\n\"Ihr Herzschlag verrät sie.\"" }
entries[118266] = { ["name"] = "Goldkaliriei", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr könnt es nicht aufbrechen und es ist sehr schwer. Sind die Gerüchte etwa wahr?\"\nVerkaufspreis:" }
