entries[118327] = { ["name"] = "Rezeptidee: Gorgronder Fischsuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Zubereitung einer Gorgronder Fischsuppe.\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBenötigt Kochkunst von Draenor (1)\n\nGorgronder Fischsuppe\nBenutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet für 1 Stunde 10 Vielseitigkeit.\n\nWenn Ihr dieses Gericht kostet, besteht eine Chance, dass Ihr das Rezept erlernt.\nVerkaufspreis:\nBenötigt Grollhufwürstchen (5), Sämige Schleichersuppe (5), Gorgrondfliegenfalle" }
entries[118328] = { ["name"] = "Rezeptidee: Festmahl des Blutes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Zubereitung eines Festmahls des Blutes.\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBenötigt Kochkunst von Draenor (1)\n\nFestmahl des Blutes\nBenutzen: Sättigt bis zu 30 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl des Blutes.\n\nDabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\nVerkaufspreis:\nBenötigt Rohes Elekkfleisch (10), Rohes Eberfleisch (10), Rohes Talbukfleisch (10), Rohes Flussbestienfleisch (10), Rylakei (10), Rohes Grollhuffleisch (10)" }
entries[118329] = { ["name"] = "Rezeptidee: Festmahl der Gewässer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Zubereitung eines Festmahls der Gewässer.\nRezept für 4 Portionen. Die tatsächliche Anzahl an Portionen hängt von Eurer Kochfertigkeit ab. Während des Kochens fällt Euch vielleicht eine neue Rezeptidee ein.\nBenötigt Kochkunst von Draenor (1)\n\nFestmahl der Gewässer\nBenutzen: Sättigt bis zu 10 Mitglieder Eures Schlachtzugs oder Eurer Gruppe mit einem Festmahl der Gewässer.\n\nDabei besteht eine Chance, dass Ihr das Rezept erlernt.\n\nStellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und der Wert, auf den Ihr abgestimmt seid, wird 1 Stunde lang um 550 erhöht.\nVerkaufspreis:\nBenötigt Seeskorpionsegment (10), Fleisch eines Tiefenschluckaals (10), Fleisch eines blinden Seestörs (10), Fleisch eines dicken Schläfers (10), Feuerammonittentakel (10), Fleisch eines kieferlosen Schleichers (10)" }
entries[118330] = { ["name"] = "Waffenstapel", ["text"] = "Questgegenstand\nBenutzen: Platziert einen Waffenstapel zu Euren Füßen.\n\nNahe Gefangene werden sich bewaffnen und Gegner angreifen.\n\nEs kann immer nur ein Waffenstapel platziert sein. Hält 15 Sek. lang an. (15 Sek. Abklingzeit)" }
