entries[118375] = { ["name"] = "Arkankristallmodul", ["text"] = "Handelspostenmodul\n\"Die Teile für dieses Modul sind in Draenorinvasionen und Draenorschlachtzügen zu finden sowie im Auktionshaus.\"\nVerkaufspreis:" }
