entries[118379] = { ["name"] = "Zyklisches Energiemodul", ["text"] = "Handelspostenmodul\n\"Die Teile für dieses Modul könnt Ihr bei Kreaturen in Gorgrond, dem Frostfeuergrat und den Spitzen von Arak finden. Sie können auch im Auktionshaus gehandelt werden.\"\nVerkaufspreis:" }
entries[118380] = { ["name"] = "Kappe des obersten Anglers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDauer: 7 tagen (Realzeit)Kopf Kosmetisch\nAnlegen: +5 Angelfertigkeit.\nBenötigt Angeln (1)\n\"Eine Woche lang seid Ihr der Angelkönig dieser Welt!\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
