entries[118392] = { ["name"] = "Verbrannter Klumpen", ["text"] = "\"Ein verkohlter, unerkennbarer Haufen Irgendetwas, der möglicherweise irgendwann einmal nützlich war. Nur wenige Dinge überstehen Lava.\"\nVerkaufspreis:" }
