entries[118416] = { ["name"] = "Fischrogen", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang eine Erhöhung eines Werts um 6 . Kann für manche effektiver sein als für andere.\nVerkaufspreis:" }
entries[118417] = { ["name"] = "Kiste überschüssiges Material", ["text"] = "Questgegenstand\n\"Voll mit Nägeln, Decken und weiteren Gegenständen, die gerade herumlagen.\"" }
entries[118418] = { ["name"] = "Ein Becher Augenöffner", ["text"] = "Questgegenstand\nBenutzen: Spritzt Kaffee auf einen schlummernden Händler. (5 Sek. Abklingzeit)\n\"Der Kaffeebecher kann benutzt werden, um einen Händler zu wecken.\"" }
entries[118424] = { ["name"] = "Blinder Bleichfisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, verwandelt Ihr Euch womöglich in etwas anderes.\n\"Wer würde so etwas essen?\"\nVerkaufspreis:" }
entries[118425] = { ["name"] = "Nesingwarys verlorenes Horn", ["text"] = "Ashran\nWird beim Aufheben gebunden\nBenutzen: Lasst eine Wildtierstampede über die Straße des Ruhms stürmen, die Gegner in die Luft schleudert und ihnen körperlichen Schaden zufügt.\n\nKann nur an der Straße des Ruhms in Ashran verwendet werden. (1 Stunde Abklingzeit)\n\"An der Seite des Horns ist H.W. eingraviert.\"" }
entries[118426] = { ["name"] = "Beschwörungsschriftrolle für Yu'lon, die Jadeschlange", ["text"] = "Ashran\nWird beim Aufheben gebunden\nBenutzen: Lässt die himmlische Jadeschlange an der Straße des Ruhms erscheinen, wodurch alle verbündeten Ziele vollständig geheilt und von allen magischen sowie Gift- und Krankheitseffekten befreit werden.\n\nKann nur an der Straße des Ruhms in Ashran verwendet werden. (1 Stunde Abklingzeit)\n\"Auf der Seite dieses Sattels steht Fei geschrieben.\"" }
entries[118427] = { ["name"] = "Signierte Hearthstone-Karte", ["text"] = "Spielzeug\nBenutzen: Dreht Eure Karte um und zeigt, was Ihr habt! (10 Sek. Abklingzeit)\n\"Von Trump und Reckful höchstpersönlich unterschrieben. Nicht schlecht.\"\nVerkaufspreis:" }
entries[118428] = { ["name"] = "Chili der Legion", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. 8173 Gesundheit und ( 2125 / 5 * 20) Mana wieder her. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang eine Erhöhung eines Werts um 10 .\n\"Brennt im Mund.\"\nVerkaufspreis:" }
entries[118429] = { ["name"] = "Formel: Umhang - Hauch des Tempos", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Umhänge dauerhaft zu verzaubern, sodass das Tempo um [Quellwert] erhöht wird.\nEinen Umhang dauerhaft verzaubern, sodass das Tempo um 2 erhöht wird.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)", ["unresolvedValues"] = true }
