entries[118458] = { ["name"] = "Formel: Waffe - Mal des Donnerfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie gelegentlich den kritischen Trefferwert erhöhen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal Euer kritischer Trefferwert 6 Sek. lang um 77 erhöht wird. Wenn der Effekt aktiv ist, können kritische Heilungen und Angriffe die Dauer verlängern.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)" }
entries[118460] = { ["name"] = "Formel: Waffe - Mal des Kriegshymnenklans", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie gelegentlich das Tempo erhöhen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal das Tempo um ( 15 * 10) erhöht wird, bevor sich dieser Wert alle 2 Sek. um 10% verringert.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)" }
entries[118461] = { ["name"] = "Formel: Waffe - Mal des Frostwolfs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie gelegentlich den kritischen Trefferwert erhöhen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal der kritische Trefferwert 6 Sek. lang um 77 erhöht wird. Der Effekt ist 2-mal stapelbar.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)" }
entries[118462] = { ["name"] = "Formel: Waffe - Mal des Schattenmonds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie gelegentlich die Vielseitigkeit erhöhen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal die Vielseitigkeit 15 Sek. lang um 77 erhöht wird.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)" }
entries[118463] = { ["name"] = "Formel: Waffe - Mal des Schwarzfels", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie gelegentlich die Bonusrüstung erhöhen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal die Vielseitigkeit 12 Sek. lang um 77 erhöht wird. Der Effekt kann nur auftreten, wenn Eure Gesundheit unter 60% liegt.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)" }
entries[118467] = { ["name"] = "Formel: Waffe - Mal des Blutenden Auges", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, Nahkampfwaffen dauerhaft zu verzaubern, sodass sie gelegentlich die Meisterschaft erhöhen.\nEine Nahkampfwaffe dauerhaft verzaubern, sodass manchmal die Meisterschaft 12 Sek. lang um 77 erhöht wird.\n\nKann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Verzauberkunst von Draenor (1)" }
entries[118468] = { ["name"] = "Frisches Brot", ["text"] = "Questgegenstand\n\"Baros würde das zu schätzen wissen.\"" }
entries[118469] = { ["name"] = "Schwarze Klaue von Sethe", ["text"] = "Wird beim Aufheben gebunden\n\"Eine unheimliche dunkle Substanz tropft ununterbrochen von ihr herab. Eure Ausbildungsreittiere werden dadurch recht nervös.\"" }
entries[118470] = { ["name"] = "Garnzahnhalskette", ["text"] = "Wird beim Aufheben gebunden\n\"Riecht nach einem Wolfsrudel. Eure Ausbildungsreittiere werden dadurch ausgesprochen nervös.\"" }
entries[118471] = { ["name"] = "Geborgene Teile", ["text"] = "Questgegenstand\n\"Manche können wiederverwertet werden, aber nicht viele.\"" }
entries[118472] = { ["name"] = "Wildblut", ["text"] = "Handwerksmaterial\n\"Aus der Scheune der Garnison oder von Alchemisten hergestellt. Kann im Auktionshaus gekauft und verkauft werden.\"\nVerkaufspreis:" }
entries[118473] = { ["name"] = "Kleine Tasche mit geborgenen Teilen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Durchwühlt den Sack nach allem, was nützlich sein könnte. Nur in Eurer Wiederverwertung möglich." }
entries[118474] = { ["name"] = "Der ultimative Tanzleitfaden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt einen Anhänger die Eigenschaft 'Tänzer' erlernen. Dabei wird eine existierende Eigenschaft ersetzt.\n\"Alles, was ein Anhänger über die angesagtesten Tanzschritte wissen muss. – Patrick Schwitzi\"\nVerkaufspreis:" }
entries[118475] = { ["name"] = "Hearthstone-Strategieführer", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lässt einen Anhänger die Eigenschaft 'Hearthstone-Profi' erlernen. Dabei wird eine existierende Eigenschaft ersetzt.\n\"Verwandelt einen gewöhnlichen Anhänger in ein taktisches Genie.\"\nVerkaufspreis:" }
entries[118476] = { ["name"] = "Bauplan: Eisenschredders Schredder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Eisenschredders Schredder.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nEisenschredders Schredder\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nDistanz Schusswaffe\n7 - 13 Schaden Geschwindigkeit 3.00\n(3.3 Schaden pro Sekunde)\n+5 Beweglichkeit\n+7 Ausdauer\nHaltbarkeit 120 / 120\n\"Für Ingenieure ein Kunstwerk. Für Jäger ein Werkzeug für die Kunst des Tötens.\"\nVerkaufspreis:\nBenötigt Getriebefederteile (100)\nOptionale Reagenzien: [] (#50) , Echteisenabzug (#239)" }
entries[118477] = { ["name"] = "Bauplan: Glotz' Raketenspalter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Glotz' Raketenspalter.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nGlotz' Raketenspalter\nBenutzen: Bringt dauerhaft eine spezielle Vorrichtung an einer Distanzwaffe an, sodass manchmal Euer Tempo 12 Sek. lang um 115 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Getriebefederteile (20)" }
entries[118478] = { ["name"] = "Bauplan: Megawattglühfaden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines Megawattglühfadens.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nMegawattglühfaden\nBenutzen: Bringt dauerhaft eine elektrische Vorrichtung an einer Distanzwaffe an, sodass manchmal Euer kritischer Trefferwert 12 Sek. lang um 115 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\n\"Alles ist besser unter Strom.\"\nVerkaufspreis:\nBenötigt Getriebefederteile (20)" }
entries[118480] = { ["name"] = "Bauplan: Findels Plünderang", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Findels Plünderang.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nFindels Plünderang\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Sammelt die Beute von einer Leiche in der Nähe ein. Kann nur in Draenor verwendet werden. (3 Sek. Abklingzeit)\nVerkaufspreis:\nBenötigt Getriebefederteile (50)" }
entries[118481] = { ["name"] = "Bauplan: Weltschrumpfer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines Weltschrumpfers.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nWeltschrumpfer\nSpielzeug\nBenutzen: Schrumpft die gesamte Welt 5 Min. lang oder bis Ihr angreift. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)\n\"Übermäßiger Gebrauch kann zu dauerhafter Schrumpfung führen.\"\nVerkaufspreis:\nBenötigt Getriebefederteile (50)" }
entries[118484] = { ["name"] = "Bauplan: Mechanischer Axtschnabel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines mechanischen Axtschnabels.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nMechanischer Axtschnabel\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nBeschwört Euren mechanischen Tukan oder gibt ihn wieder frei.\n80 ( 80)\nVerkaufspreis:\nBenötigt Getriebefederteile (50)" }
entries[118485] = { ["name"] = "Bauplan: Lebensechter mechanischer Frosteber", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines lebensechten mechanischen Frostebers.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nLebensechter mechanischer Frosteber\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren lebensechten mechanischen Eber beschwören oder wieder freigeben.\n80 ( 80)\nVerkaufspreis:\nBenötigt Getriebefederteile (50), Prächtiges Fell (40)" }
entries[118487] = { ["name"] = "Bauplan: Persönliches Hologramm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines persönlichen Hologramms.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nPersönliches Hologramm\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erstellt 1 Min. lang ein temporäres Hologramm von Euch selbst. (5 Min Abklingzeit)\n\"Das Bild kann auf einige Emotes reagieren.\"\nVerkaufspreis:\nBenötigt Getriebefederteile (50)" }
entries[118488] = { ["name"] = "Bauplan: Wurmlochzentrifuge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung einer Wurmlochzentrifuge.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nWurmlochzentrifuge\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Erschafft ein rotierendes Wurmloch, das der Ingenieur verwenden kann, um Draenor zu bereisen. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nBenötigt Getriebefederteile (50)" }
entries[118489] = { ["name"] = "Bauplan: Wechselblaster", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines Wechselblasters.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nWechselblaster\nWird bei Benutzung gebunden\nBenutzen: Tauscht Eure Position mit der eines anderen Gruppenmitglieds. Kann nicht im Kampf genutzt werden. (1 Min Abklingzeit)\n\"Achtung: Der Tausch mit einem Ziel, das einen neuralen Stummschalter verwendet, ist lebensgefährlich.\"\nVerkaufspreis:\nBenötigt Getriebefederteile (50), Temporaler Kristall" }
entries[118490] = { ["name"] = "Bauplan: Blingtron 5000", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung eines Blingtron 5000.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nBlingtron 5000\nWird beim Aufheben gebunden\nSpielzeug\nBenutzen: Setzt den verbesserten Blingtron 5000 zusammen, einen wilden, aber großzügigen Roboter. Einerseits lässt er Spielercharakteren einmal am Tag kleine Präsente zukommen, anderseits bekämpft er andere Blingtron-Einheiten bis zum Tode. (4 Std. Abklingzeit)\nBenötigt Ingenieurskunst von Draenor (1)\nBenötigt Getriebefederteile (100)" }
entries[118491] = { ["name"] = "Bauplan: Kuppelschmiers Sperrzahnrad", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Kuppelschmiers Sperrzahnrad.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nKuppelschmiers Sperrzahnrad\nBenötigt Getriebefederteile (70), Magisches Feuer (15), Wildblut (15)" }
entries[118492] = { ["name"] = "Bauplan: Mordens außergewöhnlicher Apparat", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenötigt Ingenieurskunst (1)\n\"Die Schrift auf dem Bauplan ist verblasst.\"\nVerkaufspreis:" }
entries[118493] = { ["name"] = "Bauplan: Didis kunstvolle Konstruktion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Didis kunstvoller Konstruktion.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nDidis kunstvolle Konstruktion\nBenötigt Echteisenerz (15), Schwarzfelserz (15)" }
entries[118495] = { ["name"] = "Bauplan: Hemets Herzsucher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung von Hemets Herzsucher.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nHemets Herzsucher\nBenutzen: Bringt dauerhaft eine fortschrittliche Zielvorrichtung an einer Distanzwaffe an, sodass manchmal Eure Meisterschaft 12 Sek. lang um 115 erhöht wird, wenn Ihr Distanzschaden verursacht.\n\nDurch das Anbringen der Vorrichtung an einer Distanzwaffe wird diese seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\n\"Wenn es eines gibt, das Nesingwary verbessern kann, dann eine Tötungsmaschine.\"\nVerkaufspreis:\nBenötigt Getriebefederteile (20)" }
entries[118497] = { ["name"] = "Bauplan: Cybergenetische Mechbrille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung einer cybergenetischen Mechbrille.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nCybergenetische Mechbrille\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nKopf Kette\n8 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nBenötigt Getriebefederteile (100)\nOptionale Reagenzien: [] (#50) , Kuppelschmiers Sperrzahnrad (#238)" }
entries[118498] = { ["name"] = "Bauplan: Nachtsichtmechbrille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch die Herstellung einer Nachtsichtmechbrille.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nNachtsichtmechbrille\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nKopf Leder\n6 Rüstung\n+5 [Beweglichkeit oder Intelligenz]\n+7 Ausdauer\nHaltbarkeit 100 / 100\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen.\nBenötigt Ingenieurskunst von Draenor (1)\nVerkaufspreis:\nBenötigt Getriebefederteile (100)\nOptionale Reagenzien: [] (#50) , Kuppelschmiers Sperrzahnrad (#238)" }
