entries[118605] = { ["name"] = "Technik: Stab des Kristallfeuers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Stab des Kristallfeuers beschriftet.\nBenötigt Inschriftenkunde von Draenor (1)\nVerkaufspreis:\nStab des Kristallfeuers\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)\nZweihändig Stab\n5 - 7 Schaden Geschwindigkeit 3.60\n(1.7 Schaden pro Sekunde)\n+20 Intelligenz\n+7 Ausdauer\nHaltbarkeit 120 / 120\nVerkaufspreis:\nBenötigt Einfaches Holz , Kriegsbemalung (100)\nOptionale Reagenzien: [] (#49) , Waffenkristall (#242)" }
