entries[118613] = { ["name"] = "Technik: Schattenfoliant", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Schattenfolianten beschriftet.\nBenötigt Inschriftenkunde von Draenor (1)\nVerkaufspreis:\nSchattenfoliant\nWird beim Anlegen gebunden\nIn Schildhand geführt\n+7 Intelligenz\n+3 Ausdauer\nVerkaufspreis:\nBenötigt Leichtes Pergament (10), Kriegsbemalung (50)\nOptionale Reagenzien: [] (#49) , Waffenkristall (#242)" }
