entries[118935] = { ["name"] = "Immergrüner Wedel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stellt 6 Sek. lang alle 1 Sek. 15% Gesundheit und Mana wieder her. Jeglicher erlittene Schaden beendet das Blühen. Kann nur in Draenor genutzt werden. (5 Min Abklingzeit)\n\"Jeder Riss in diesem Blatt schließt sich augenblicklich wieder.\"" }
entries[118936] = { ["name"] = "Anleitung zum Leerenrufen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSchmuck\nBenutzen: Beschwört einen gebundenen Leerrufer, der 10 Min. lang für Euch kämpft. (1 Stunde Abklingzeit)\n\"Die Wörter sind in einer Tinte geschrieben, die so dunkel ist, dass sie das Licht von den Seiten zieht.\"\nVerkaufspreis:" }
entries[118937] = { ["name"] = "Gamons Zopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Umklammert fest den Zopf, dann wird Gamon bei Euch sein. (Procchance: 10%, 3Min. Abklingzeit) (2 Std. Abklingzeit)\n\"Gamon wird uns retten!\"" }
entries[118938] = { ["name"] = "Manasturms Verdoppler", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Fügt der Welt einen weiteren Manasturm hinzu. Das hat ihr gerade noch gefehlt. (Procchance: 10%, 3Min. Abklingzeit) (2 Std. Abklingzeit)\n\"Jetzt stehst du da wie 'ne Eins, Millhaus!\"" }
